-- alternative-finance-group-afg-zwartkop (researched)
UPDATE businesses SET description = 'Alternative Finance Group, known as AFG, is a non-bank finance provider in Centurion offering fast, flexible business funding across South Africa. Its solutions include asset-backed lending, purchase order finance, invoice discounting and property bridging, with amounts of up to R50 million, and the group says it has supported more than 1,295 businesses and funded more than R2.3 billion.

Each product has its own criteria. Asset-backed lending requires an annual turnover of about R1 million and a 2:1 asset-to-loan ratio, invoice discounting requires an approved invoice from a client, and purchase order finance requires a verified government purchase order with a profit margin of at least 30 percent. Applications are completed online, after which a specialist makes contact. It suits established businesses with government or corporate contracts or property to bridge, and the office is in Centurion Gate Office Park on Akkerboom Street.', source_urls = json_insert(CASE WHEN json_valid(source_urls) AND json_type(source_urls) = 'array' THEN source_urls ELSE '[]' END, '$[#]', 'https://afg.africa/'), description_enriched_at = datetime('now') WHERE slug = 'alternative-finance-group-afg-zwartkop' AND description = 'Alternative Finance Group (AFG) is a non-bank finance provider in Centurion offering funding to small and medium enterprises, including asset-backed short-term loans, purchase order funding, bridging finance and invoice discounting through its group companies CorpFin, ProfitHub, QuickBridge and DiscountDesk.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
