-- arc-onderstepoort-veterinary-institute-onderstepoort (researched)
UPDATE businesses SET description = 'The ARC-Onderstepoort Veterinary Institute is the veterinary research campus of the Agricultural Research Council, a flagship campus of the ARC on Old Soutpan Road in Pretoria. It has a long tradition of veterinary research dating back to its founding in 1908 and is recognised internationally as a centre of excellence for animal health and welfare.

The campus develops vaccines and diagnostic tests using molecular techniques, produces vaccines against diseases such as foot-and-mouth disease and tick-borne diseases, and provides veterinary diagnostic services. It works as a collaborating centre for the World Organisation for Animal Health and the FAO in animal disease surveillance, control and emergency preparedness across Africa. It suits veterinary services and animal-health bodies that rely on its diagnostics, vaccines and surveillance support.', source_urls = json_insert(CASE WHEN json_valid(source_urls) AND json_type(source_urls) = 'array' THEN source_urls ELSE '[]' END, '$[#]', 'https://www.fao.org/agris/data-provider/arc-onderstepoort-veterinary-research-campus', '$[#]', 'https://www.arc.agric.za/arc-ovi/Pages/ARC-OVI-Homepage.aspx'), description_enriched_at = datetime('now') WHERE slug = 'arc-onderstepoort-veterinary-institute-onderstepoort' AND description = 'ARC-Onderstepoort Veterinary Institute is a veterinary research campus of the Agricultural Research Council, recognised internationally since 1908 for its work on livestock and wildlife disease diagnostics, vaccine development (including for foot-and-mouth disease and tick-borne diseases), and animal health surveillance.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
